CREATE TABLE `soal` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_ujian` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nomer_soal` int NOT NULL,
  `kode_soal` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipe` enum('pg','pg_kompleks','bs','jodohkan','uraian','menjodohkan') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `soal` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `a` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `b` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `c` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `d` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `e` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `pasangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `kunci` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=39991 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
